import React, { useState } from 'react';

export default function BlocoEtapaVisual({ etapaId = 1 }) {
  const [mensagem, setMensagem] = useState('');
  const [opcoes, setOpcoes] = useState([]);
  const [usarOpcoes, setUsarOpcoes] = useState(false);

  const adicionarOpcao = () => {
    const nova = { texto: '', acao: 'mensagem', destino: '' };
    setOpcoes([...opcoes, nova]);
  };

  const atualizarOpcao = (index, campo, valor) => {
    const novas = [...opcoes];
    novas[index][campo] = valor;
    setOpcoes(novas);
  };

  return (
    <div className="border rounded p-4 bg-white shadow mb-4 max-w-2xl mx-auto">
      <h2 className="font-bold text-lg mb-2">Etapa #{etapaId}</h2>

      <label className="block text-sm font-medium mb-1">Mensagem para o cliente:</label>
      <textarea
        value={mensagem}
        onChange={(e) => setMensagem(e.target.value)}
        placeholder="Digite a mensagem dessa etapa..."
        rows={3}
        className="w-full border rounded p-2 mb-4"
      />

      <label className="inline-flex items-center mb-4">
        <input
          type="checkbox"
          checked={usarOpcoes}
          onChange={() => setUsarOpcoes(!usarOpcoes)}
          className="mr-2"
        />
        Adicionar opções interativas
      </label>

      {usarOpcoes && (
        <div className="space-y-3">
          {opcoes.map((opcao, index) => (
            <div key={index} className="flex gap-2 items-center">
              <input
                type="text"
                placeholder={`Texto da opção ${index + 1}`}
                value={opcao.texto}
                onChange={(e) => atualizarOpcao(index, 'texto', e.target.value)}
                className="border rounded p-2 w-1/2"
              />
              <select
                value={opcao.acao}
                onChange={(e) => atualizarOpcao(index, 'acao', e.target.value)}
                className="border rounded p-2 w-1/3"
              >
                <option value="mensagem">➡️ Nova mensagem</option>
                <option value="etapa">🔁 Ir para etapa</option>
                <option value="redirecionar">☎️ Redirecionar</option>
              </select>
              {opcao.acao !== 'mensagem' && (
                <input
                  type="text"
                  placeholder={opcao.acao === 'etapa' ? 'Etapa destino' : 'Número WhatsApp'}
                  value={opcao.destino}
                  onChange={(e) => atualizarOpcao(index, 'destino', e.target.value)}
                  className="border rounded p-2 w-1/3"
                />
              )}
            </div>
          ))}
          <button
            onClick={adicionarOpcao}
            className="bg-blue-500 text-white text-sm px-3 py-1 rounded hover:bg-blue-600"
          >
            + Adicionar Opção
          </button>
        </div>
      )}
    </div>
  );
}
